import re
from fractions import Fraction


def fraction_expr(s: str) -> str:
    if not isinstance(s, str):
        raise ValueError("expression must be a string")

    token_re = re.compile(r"\s*(?:(\d+/\d+)|(\d+)|([()+\-*]))")
    tokens = []
    pos = 0

    while pos < len(s):
        match = token_re.match(s, pos)
        if not match:
            if s[pos:].strip() == "":
                break
            raise ValueError("malformed input")

        fraction, integer, operator = match.groups()
        if fraction is not None:
            numerator, denominator = fraction.split("/")
            try:
                value = Fraction(int(numerator), int(denominator))
            except ZeroDivisionError as exc:
                raise ValueError("zero denominator") from exc
            tokens.append(("value", value))
        elif integer is not None:
            tokens.append(("value", Fraction(int(integer), 1)))
        else:
            tokens.append((operator, operator))

        pos = match.end()

    if not tokens:
        raise ValueError("empty expression")

    index = 0

    def parse_expression():
        nonlocal index
        value = parse_term()

        while index < len(tokens) and tokens[index][0] in ("+", "-"):
            operator = tokens[index][0]
            index += 1
            right = parse_term()
            value = value + right if operator == "+" else value - right

        return value

    def parse_term():
        nonlocal index
        value = parse_factor()

        while index < len(tokens) and tokens[index][0] == "*":
            index += 1
            value *= parse_factor()

        return value

    def parse_factor():
        nonlocal index

        if index >= len(tokens):
            raise ValueError("missing term")

        token_type, token_value = tokens[index]

        if token_type == "-":
            index += 1
            return -parse_factor()

        if token_type == "(":
            index += 1
            value = parse_expression()
            if index >= len(tokens) or tokens[index][0] != ")":
                raise ValueError("missing closing parenthesis")
            index += 1
            return value

        if token_type == "value":
            index += 1
            return token_value

        raise ValueError("malformed input")

    result = parse_expression()

    if index != len(tokens):
        raise ValueError("malformed input")

    if result.denominator == 1:
        return str(result.numerator)
    return f"{result.numerator}/{result.denominator}"
